export function cropBounds(d,w,h,W=160,H=120){const size=Math.min(w,h,Math.max(90,Math.max((d.maxX-d.minX+1)*w/W,(d.maxY-d.minY+1)*h/H)*3));return{x:Math.max(0,Math.min(w-size,(d.minX+d.maxX+1)/2*w/W-size/2)),y:Math.max(0,Math.min(h-size,(d.minY+d.maxY+1)/2*h/H-size/2)),size};}
export function strongEvidence(results){const bug=results.find(r=>r.label==='a close-up photograph of a real insect or spider')?.score??0;const other=Math.max(0,...results.filter(r=>r.label!=='a close-up photograph of a real insect or spider').map(r=>r.score));return bug>=.90&&bug-other>=.70;}
export function motion(gray,previous,W=160,H=120){if(!previous)return{shake:false,candidates:[]};let moved=0;const mask=new Uint8Array(gray.length);for(let y=1;y<H-1;y++)for(let x=1;x<W-1;x++){const i=y*W+x,delta=Math.abs(gray[i]-previous[i]);if(delta>24)moved++;const edge=Math.abs(4*gray[i]-gray[i-1]-gray[i+1]-gray[i-W]-gray[i+W]);if(delta>24&&edge>35)mask[i]=1;}if(moved/gray.length>.12)return{shake:true,candidates:[]};const candidates=[];for(let i=0;i<mask.length;i++){if(!mask[i])continue;const stack=[i];mask[i]=0;let minX=W,minY=H,maxX=0,maxY=0,n=0;while(stack.length){const p=stack.pop(),x=p%W,y=Math.floor(p/W);n++;minX=Math.min(minX,x);maxX=Math.max(maxX,x);minY=Math.min(minY,y);maxY=Math.max(maxY,y);for(const [nx,ny]of[[x-1,y],[x+1,y],[x,y-1],[x,y+1]]){if(nx<0||nx>=W||ny<0||ny>=H)continue;const q=ny*W+nx;if(mask[q]){mask[q]=0;stack.push(q);}}}const area=(maxX-minX+1)*(maxY-minY+1);if(n>=6&&n<=220&&area<=650&&area>=12&&maxX-minX<40&&maxY-minY<40)candidates.push({minX,minY,maxX,maxY,n});}return{shake:false,candidates:candidates.sort((a,b)=>b.n-a.n).slice(0,5)};}
export function sameTarget(a,b){return !!a&&!!b&&Math.hypot((a.minX+a.maxX-b.minX-b.maxX)/2,(a.minY+a.maxY-b.minY-b.maxY)/2)<10;}
